import{_ as s,C as n,o as i,c as r,j as t,a as o,E as h,ak as l}from"./chunks/framework.sV-XtlWr.js";const c="/screenshots/project-integration-auto-create.png",b=JSON.parse('{"title":"Issue automation","description":"Rules that file a Jira issue for a failure that keeps failing on the branches and environments you choose, and keep its comments and description current as the failure evolves.","frontmatter":{"title":"Issue automation","description":"Rules that file a Jira issue for a failure that keeps failing on the branches and environments you choose, and keep its comments and description current as the failure evolves.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/issue-automation.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/issue-automation.html"}],["meta",{"property":"og:title","content":"Issue automation | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Rules that file a Jira issue for a failure that keeps failing on the branches and environments you choose, and keep its comments and description current as the failure evolves."}]]},"headers":[],"relativePath":"features/issue-automation.md","filePath":"features/issue-automation.md","lastUpdated":1791619990000}'),d={name:"features/issue-automation.md"};function u(f,e,m,g,p,w){const a=n("Needs");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"issue-automation",tabindex:"-1"},[o("Issue automation "),t("a",{class:"header-anchor",href:"#issue-automation","aria-label":'Permalink to "Issue automation"'},"​")],-1)),h(a,{reporter:"",admin:""}),e[1]||(e[1]=l('<p><a href="./issue-tracking.html">Issue tracking</a> files an issue when someone clicks <strong>Create issue</strong>. Issue automation does it for them: after each run, Piwi files an issue for every failure that a project&#39;s <strong>rules</strong> say has failed long enough, on the branches and environments that matter, and keeps the issue&#39;s comments and description current as the failure evolves. Everything is <strong>off by default</strong> and set per project, under <strong>Project → Settings → Issue tracker</strong>.</p><div class="doc-screenshot"><img src="'+c+'" alt="The Automatic creation block of a project&#39;s issue tracker settings: two rules, one for release branches at the first occurrence and one for the default branch in staging after three occurrences in two runs over a day, the guards, and a preview listing one open failure filed at its next occurrence and one waiting on a threshold"></div><h2 id="automatic-creation" tabindex="-1">Automatic creation <a class="header-anchor" href="#automatic-creation" aria-label="Permalink to &quot;Automatic creation&quot;">​</a></h2><p>Switch on <strong>File issues automatically</strong> and give the project one or more rules. After a run finishes, Piwi checks each <a href="/guide/concepts.html#error-fingerprint-failure-cluster">failure cluster</a> that failed in it against the rules, in order. The first rule the cluster meets files the issue; a cluster that meets none yet waits for its next failure.</p><p>A rule counts only the runs it names:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Branches</strong></td><td>Branch names or <code>*</code> patterns (<code>release/*</code>). With <strong>Default branch</strong> on, the project&#39;s default branch too, whatever it is named. Nothing named: every branch.</td></tr><tr><td><strong>Environments</strong></td><td>Environment names or <code>*</code> patterns (<code>prod*</code>). Nothing named: every environment.</td></tr><tr><td><strong>Occurrences</strong></td><td>The failing executions counted in those runs.</td></tr><tr><td><strong>Runs</strong></td><td>The distinct runs among them, so one run with ten failing retries counts once.</td></tr><tr><td><strong>Days</strong></td><td>The days since the first counted occurrence, measured at the run being checked.</td></tr><tr><td><strong>Test tags</strong></td><td>Only failures of a test carrying one of these tags (<code>@critical</code>). Nothing named: every test.</td></tr><tr><td><strong>Extra labels</strong></td><td>Labels added to the issues this rule files, on top of the binding&#39;s.</td></tr></tbody></table><p>The run being checked must be one the rule counts: a failure that met a rule on <code>main</code> is filed by its next failure on <code>main</code>, never by a run on a feature branch. A failure that stops failing is never filed, whatever its counts.</p><p>A fresh binding starts with one rule: two occurrences in two runs on the default branch. Two rules a team often wants:</p><ul><li><strong>Release branches at once</strong> — branches <code>release/*</code>, one occurrence, one run, the label <code>release-blocker</code>.</li><li><strong>The default branch when it persists</strong> — the default branch in <code>staging</code>, three occurrences in two runs over a day.</li></ul><p>Whatever the rules say, a cluster is <strong>never</strong> filed automatically when it is resolved, ignored or snoozed, when an issue still tracks it or its filing is queued, or when it looks flaky (one of its tests passed on a retry since it first failed, or every one passed at the commit it failed at), unless <em>Leave out failures that look flaky</em> is off. Two more guards hold:</p><ul><li><strong>An open issue in the tracker already carries the failure&#39;s labels</strong> (<code>piwi-cluster-&lt;id&gt;</code> or <code>piwi-fp-&lt;hash&gt;</code>): Piwi leaves the link to a person. The cluster&#39;s Activity and Issue line name the issue it found and offer <em>Link an issue</em>, beside a Done issue too. An issue the cluster already links is left for the next sync to read back.</li><li><strong>The daily cap</strong>: at most this many issues filed automatically per project in any 24 hours (default 5).</li></ul><p>With <a href="./issue-tracking.html#the-project-binding">owner routes</a>, an issue goes to the route of the cluster&#39;s owner (its assignee, else the <code>piwi:owner</code> annotation, else CODEOWNERS). A failure whose owner matches no route is filed only with <em>File owners with no matching route into the default project</em> on.</p><p>The issue is filed through the same path as a click: the same body, labels and <a href="./issue-tracking.html#what-it-does-exactly">dedupe by cluster</a>, the same <a href="./issue-tracking.html#required-jira-fields">required fields</a>. An issue that is Done, or whose link was removed, no longer tracks the failure, so a rule files a new one. The exception is a Done issue the <a href="./issue-tracking.html#keep-the-ticket-honest">reopen transition</a> is moving out of Done after a regression: until the next sync reads that issue back, a rule files nothing beside it. An automatic create the tracker would refuse for a field the binding leaves empty is recorded as a failed action, naming the field.</p><h3 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h3><p><strong>Preview</strong> evaluates the rules as the form holds them, before you save, against the project&#39;s open failures that no issue tracks yet. It lists the ones a rule files at their next occurrence in a run it counts, the ones waiting on a threshold (<em>Waiting on rule 1: 1 of 2 runs</em>), and the ones left out with the reason, with the issues already filed automatically in the last 24 hours and any field the tracker requires that the binding leaves empty. Nothing is written.</p><h2 id="the-runs-that-write" tabindex="-1">The runs that write <a class="header-anchor" href="#the-runs-that-write" aria-label="Permalink to &quot;The runs that write&quot;">​</a></h2><p><strong>Runs that write to the ticket</strong> is a second scope, for the writes that follow a tracked issue: the fix, regression and still-failing comments, the transitions, and the description updates. It takes branches, the default branch and environments like a rule, and every run when it names nothing. A fix verified on a feature branch then leaves the issue alone when the scope names <code>main</code>.</p><p>Some runs never write to a tracker, whatever the scope: a run from an editor, a Flake Lab or probe run, a bisect step or a reproduction, a run flagged as an <a href="./environment-incidents.html">environment incident</a>, and a developer&#39;s local or desktop run of part of the suite (<a href="/reference/test-metadata.html#run-origin">run origin</a>).</p><h2 id="comments-and-description-updates" tabindex="-1">Comments and description updates <a class="header-anchor" href="#comments-and-description-updates" aria-label="Permalink to &quot;Comments and description updates&quot;">​</a></h2><p>Each of these is a switch in <strong>Keep the ticket honest</strong>, off by default, and a durable action listed with the others:</p><ul><li><strong>&#39;Still failing&#39; note</strong> — at most once a day or once a week, and only after the chosen number of new occurrences since the last note. It says how many occurrences over how many runs, where the latest one failed, and what is new since the last note: a branch or an environment it reached, the tests it now fails in.</li><li><strong>Comment when the failure is diagnosed</strong> — when a <a href="./ai-diagnosis.html">diagnosis</a> of the cluster completes, from Piwi or from an agent: the summary, the root cause, and the category with its confidence. It needs the diagnosis switched on in what the ticket carries.</li><li><strong>Keep the description up to date</strong> — Piwi rewrites the description of an issue it filed: at most once a day after a run in which the failure failed again, and when a diagnosis completes. The rewrite keeps the language, the toggles and the share link the issue was filed with, and changes the title only on an issue a rule filed. Before writing, Piwi reads the description back: once someone has edited it in the tracker, Piwi never replaces it again, and the activity list says so. A rewrite that would change nothing is not sent.</li></ul><h2 id="what-an-automatic-issue-says" tabindex="-1">What an automatic issue says <a class="header-anchor" href="#what-an-automatic-issue-says" aria-label="Permalink to &quot;What an automatic issue says&quot;">​</a></h2><p>It opens with why it was filed: <em>Filed automatically by Piwi after 4 occurrences in 2 runs since Oct 6, 2026. Counted on main (staging).</em>, in the <a href="./issue-tracking.html#language">ticket&#39;s language</a>. The rest is the body every issue carries: what happened (occurrences over runs, every branch and environment it failed on, the latest commit), the affected tests with their owner and failure count, the most likely cause with the diagnosis category, the evidence, what to do, the issues of the same kind of failure fixed before, and the links back to Piwi.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A <a href="/operate/integrations.html#connecting-jira-cloud">connected Jira</a> and a project binding that names the Jira project and issue type.</li><li>The <strong>Edit Issues</strong> permission on the Jira project for description updates, besides the ones issue tracking needs (<a href="/operate/integrations.html#permissions-the-token-needs">permissions</a>).</li><li>The <strong>Project admin</strong> <a href="/operate/project-access.html#what-each-role-can-do">role</a> or above to change the rules.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Rules file <strong>failure clusters</strong> only: a flaky test or a whole run is filed by hand.</li><li>Rules are checked when a run finishes, not on a timer: <em>Days</em> is measured at the next failing run, and a project with no new runs files nothing.</li><li>A description edit is told apart by its text, ignoring whitespace: changing only the formatting of a description in Jira does not stop the updates.</li><li>Jira Cloud only, like <a href="./issue-tracking.html#limits">issue tracking</a>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./issue-tracking.html">Issue tracking (Jira)</a> — creating an issue by hand, the body, the key and the sync.</li><li><a href="/operate/integrations.html">Operate → Integrations</a> — connecting Jira and the permissions the token needs.</li><li><a href="./failure-clusters.html">Failure clusters</a> — what a rule counts.</li></ul>',29))])}const k=s(d,[["render",u]]);export{b as __pageData,k as default};
